import { MeshBasicNodeMaterial, MeshStandardNodeMaterial } from 'three/webgpu';
import { uv, texture, mul, add, vec2 } from 'three/tsl';
import { gsap } from 'gsap';
import {} from '@/primitives';
import {} from '@/text';
import { Group, Mesh, PlaneGeometry } from 'three';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry } = ctx.THREE;

  // Root container – the adapter will apply position/rotation/scale.
  const root = new Group();

  // Geometry for the sprite plane (unit size, will be scaled to aspect).
  const planeGeom = new PlaneGeometry(1, 1);
  const mat = new MeshBasicNodeMaterial();
  const plane = new Mesh(planeGeom, mat);
  root.add(plane);

  // Make the plane always face the camera (billboard).
  plane.onBeforeRender = (renderer, scene, camera) => {
    plane.quaternion.copy(camera.quaternion);
  };

  // Load texture and apply atlas UV mapping when ready.
  ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
    const img = tex.image;
    const texW = (img && img.width) || 1;
    const texH = (img && img.height) || 1;

    // Default to full texture if region info missing.
    const region = (config.atlasRegion && config.atlasRegion.sourceRect) || {
      x: 0,
      y: 0,
      width: texW,
      height: texH,
    };

    const u0 = region.x / texW;
    const v0 = region.y / texH;
    const u1 = (region.x + region.width) / texW;
    const v1 = (region.y + region.height) / texH;

    const scaleNode = vec2(u1 - u0, v1 - v0);
    const offsetNode = vec2(u0, v0);
    const uvNode = add(mul(uv(), scaleNode), offsetNode);

    // Assign the textured node to the material.
    mat.colorNode = texture(tex, uvNode);
    mat.needsUpdate = true;

    // Adjust plane scale to match the aspect ratio of the atlas region.
    const aspect = region.width / region.height;
    plane.scale.set(aspect, 1, 1);
  });

  // Render text content via the font atlas, if any.
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  for (const item of items) {
    const txt = ctx.fontAtlas.createText(item.text ?? '', {
      fontSize: (item.typography && item.typography.fontSize) || 39,
      color: config.visual?.colors?.paper || '#e8ecf2',
      align: 'center',
    });
    // Position text slightly in front of the plane to avoid Z‑fighting.
    txt.position.set(0, 0, 0.01);
    plane.add(txt);
  }

  // Store cleanup logic and any timelines (none in this node).
  const cleanupResources = [];

  root.userData.cleanup = () => {
    // Dispose material and geometry.
    mat.dispose();
    planeGeom.dispose();

    // Kill any GSAP timelines that might have been added in the future.
    if (cleanupResources.length) {
      cleanupResources.forEach((t) => t.kill && t.kill());
    }
    // Remove handlers container if present.
    root.userData.handlers = {};
  };

  // No event handlers for this static sprite.
  root.userData.handlers = {};

  return root;
}
